'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{createHash,webcrypto}=require('node:crypto'),{JSDOM}=require('jsdom');
const dir=__dirname,read=n=>fs.readFileSync(path.join(dir,n),'utf8'),original=read('original-slim.js'),candidate=read('candidate-slim.js'),hash=s=>createHash('sha256').update(s).digest('hex');
const input=process.env.SLIM_ONINVALID_RED==='1'?read('candidate-slim-v1.js'):candidate;
const html='<script class="anki-final-reviewed-data" type="application/json">{"as_native_index":[]}</script><section class="sf-report"><div class="sf-panel"><button data-sf-filter="all" aria-pressed="true">all</button><button data-sf-filter="2020" aria-pressed="false">2020</button><p class="sf-preview-count">显示 1 条原文</p><div class="sf-example" data-sf-year="2020">one</div><div class="sf-example" data-sf-year="2020" hidden>duplicate</div></div></section>';
function instrument(code){const at=code.lastIndexOf('    try {\n      var ');assert.ok(at>code.lastIndexOf('  async function hydrate() {'));return code.slice(0,at)+'    window.__qaActiveSlim = { refresh: refresh, request: request, slots: slots, alive: alive };\n'+code.slice(at);}
function fixture(t,opts={}){
 const dom=new JSDOM('<!doctype html><body>'+html+(opts.extra||'')+'</body>',{runScripts:'outside-only',url:'http://example.test/card'});t.after(()=>dom.window.close());const w=dom.window,d=w.document,trace=[],errors=[];w.TextEncoder=TextEncoder;Object.defineProperty(w.crypto,'subtle',{value:webcrypto.subtle});w.addEventListener('error',e=>{errors.push(e.message);e.preventDefault();});
 function handle(name){return{refresh(){trace.push(name+'.refresh');},stats(){return{errors:[]};},dispose(){trace.push(name+'.dispose');}};}
 w.AnkiFineChunkRuntime={install(){trace.push('fine.install');return handle('fine');}};
 w.AnkiReviewedChunkProjection={prepare:async data=>{trace.push('projection.prepare');return data;},install(){trace.push('projection.install');return handle('projection');}};
 w.AnkiSharedReadingBankRuntime={install(){trace.push('bank.install');const h=handle('bank');h.ready=Promise.resolve();return h;}};
 w.AnkiSameSenseGroupRuntime={install(){trace.push('group.install');return handle('group');}};
 w.AnkiResidualReviewedChunkRuntime={install(){trace.push('residual.install');return handle('residual');}};
 const profile={filter_mode:'host-after-authored-filter',id:'externally-authenticated-fixture'};
 let outerCurrent=true; if(opts.profile!==false){w.StudyCompiledProfileBridge={get(doc){assert.equal(doc,d);trace.push('bridge.get');return opts.profile||profile;},isCurrent(doc,value){assert.equal(doc,d);assert.equal(value,opts.profile||profile);return outerCurrent;}};if(opts.bridgeMissingCurrent)delete w.StudyCompiledProfileBridge.isCurrent;}
 let suppliedCurrent,disposed=0,refreshes=0,groups=0; const invalidCallbacks=[];
 const compiled={ready:opts.ready||Promise.resolve(),refresh:async slot=>{refreshes++;trace.push('compiled.refresh');throw Error('Unknown compiled slot');},applyGrouping(panel){groups++;trace.push('compiled.group');assert.equal(panel,d.querySelector('.sf-panel'));const rows=Array.from(panel.querySelectorAll('.sf-example')),visible=rows.filter(r=>!r.hidden).length;assert.equal(panel.querySelector('.sf-preview-count').textContent,'显示 '+visible+' 处原文');rows.forEach((r,n)=>{r.hidden=n>0||r.hidden;});panel.querySelector('.sf-preview-count').textContent='显示 '+rows.filter(r=>!r.hidden).length+' 条原文';},dispose(){disposed++;trace.push('compiled.dispose');}};
 w.AnkiCompiledCardRuntime={install(doc,value,options){trace.push('compiled.install');assert.equal(doc,d);assert.equal(value,opts.profile||profile);suppliedCurrent=options.isCurrent;invalidCallbacks.push(options.onInvalid);return opts.badHandle||compiled;}};
 if(opts.authored!==false)d.addEventListener('click',e=>{const button=e.target.closest('[data-sf-filter]');if(!button)return;const panel=button.closest('.sf-panel');trace.push('authored.filter');panel.querySelectorAll('[data-sf-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;panel.querySelectorAll('.sf-example').forEach(row=>{row.hidden=button.dataset.sfFilter!=='all'&&row.dataset.sfYear!==button.dataset.sfFilter;if(!row.hidden)count++;});panel.querySelector('.sf-preview-count').textContent='显示 '+count+' 处原文';e.stopPropagation();},true);
 w.eval(instrument(opts.code||input));return{w,d,trace,errors,compiled,get disposed(){return disposed;},get groups(){return groups;},get refreshes(){return refreshes;},current:()=>suppliedCurrent?.(),setOuterCurrent:value=>{outerCurrent=value;},invalidCallbacks,payload:d.querySelector('.anki-final-reviewed-data')};
}
const semantic=f=>f.trace.filter(x=>/^(fine|projection|bank|group)\./.test(x));
test('adapter exact three boundaries, unchanged unknown source, all edits inverse to original',()=>{const adapt=vm.runInNewContext(read('adapter.js')+';adaptActiveSlimCompiledProfile'),pin=hash(original);assert.equal(adapt(original,pin),candidate);assert.equal(adapt(original,'unknown'),original);assert.throws(()=>adapt(candidate,pin),/boundary/);const edits=JSON.parse(read('edits.json'));assert.equal(edits.length,3);let value=candidate;for(const [a,b]of edits.slice().reverse()){assert.equal(value.split(b).length,2);value=value.replace(b,a);}assert.equal(value,original);for(const [a]of edits)assert.throws(()=>adapt(original.replace(a,a+'\n'+a),pin),/boundary/);});
test('archived inverse evidence pins remain intact; local active-slice adapter preserves an unrelated prefix',()=>{const proof=JSON.parse(read('inverse-proof.json'));assert.equal(proof.cases.length,4);for(const item of proof.cases){assert.equal(item.byte_exact,true);assert.equal(item.input_sha256,item.inverse_sha256);assert.match(item.input_sha256,/^[a-f0-9]{64}$/);}const adapt=vm.runInNewContext(read('adapter.js')+';adaptActiveSlimCompiledProfile'),prefix='window.__unrelatedArchivedSource=true;\n',changed=adapt(prefix+original,hash(original));assert.equal(changed.slice(0,prefix.length),prefix);let inverse=changed;for(const [a,b]of JSON.parse(read('edits.json')).slice().reverse())inverse=inverse.replace(b,a);assert.equal(inverse,prefix+original);});
test('legacy absent profile preserves original full semantic path and ready output',async t=>{const a=fixture(t,{profile:false,code:original}),b=fixture(t,{profile:false});await a.w.AnkiSlimApkgHydrate();await b.w.AnkiSlimApkgHydrate();assert.deepEqual(b.trace,a.trace);assert.equal(b.d.body.innerHTML,a.d.body.innerHTML);assert.equal(b.payload.dataset.nativeState,'ready');assert.deepEqual(semantic(b),['fine.install','projection.prepare','projection.install','bank.install','group.install']);});
test('compiled skips all original semantic work but keeps real residual, lifecycle, discover and ready',async t=>{const f=fixture(t);await f.w.AnkiSlimApkgHydrate();assert.ok(f.trace.includes('compiled.install'));assert.deepEqual(semantic(f),[]);assert.ok(f.trace.includes('residual.install'));assert.equal(f.current(),true);assert.equal(f.payload.dataset.nativeState,'ready');assert.equal(f.w.__qaActiveSlim.slots.length,0);f.w.AnkiSlimApkgDispose();assert.equal(f.disposed,1);assert.equal(f.current(),false);});
test('compiled awaited ready and generation cancellation cannot mark stale payload ready or install residual',async t=>{let resolve;const ready=new Promise(r=>resolve=r),f=fixture(t,{ready}),job=f.w.AnkiSlimApkgHydrate();await Promise.resolve();assert.equal(f.payload.dataset.nativeState,undefined);f.w.AnkiSlimApkgDispose();resolve();await job;assert.equal(f.disposed,1);assert.equal(f.current(),false);assert.equal(f.payload.dataset.nativeState,undefined);assert.ok(!f.trace.includes('residual.install'));assert.deepEqual(semantic(f),[]);});
test('compiled present manifest is explicitly unsupported before binder mutation, not history support',async t=>{const extra='<details><div class="as-lazy" data-as-kind="detail"><script class="as-manifest" type="application/json">{"schema":"anki-slim-segments.v1","parts":[],"total":0}</script></div></details>',f=fixture(t,{extra});await f.w.AnkiSlimApkgHydrate();assert.equal(f.payload.dataset.nativeState,'failed');assert.ok(f.d.querySelector('.anki-final-status').textContent.includes('slotless'));assert.ok(!f.trace.includes('compiled.install'));assert.deepEqual(semantic(f),[]);});
test('compiled late manifest drift is rejected after ready before discovery or native ready',async t=>{let resolve;const f=fixture(t,{ready:new Promise(r=>resolve=r)}),job=f.w.AnkiSlimApkgHydrate();await Promise.resolve();const n=f.d.createElement('script');n.className='as-manifest';f.d.body.append(n);resolve();await job;assert.equal(f.payload.dataset.nativeState,'failed');assert.ok(f.d.querySelector('.anki-final-status').textContent.includes('non-slotless'));assert.ok(!f.trace.includes('residual.install'));});
test('compiled unknown slot calls binder refresh and rejects instead of a success no-op',async t=>{const f=fixture(t);await f.w.AnkiSlimApkgHydrate();await assert.rejects(f.w.__qaActiveSlim.refresh({panel:null}),/Unknown compiled slot/);assert.equal(f.refreshes,1);assert.deepEqual(semantic(f),[]);});
test('compiled authored filter then Slim grouping runs once with original count contract',async t=>{const f=fixture(t);await f.w.AnkiSlimApkgHydrate();f.d.querySelector('[data-sf-filter="2020"]').click();assert.equal(f.groups,1);assert.deepEqual(f.trace.slice(-2),['authored.filter','compiled.group']);assert.equal(f.d.querySelector('.sf-preview-count').textContent,'显示 1 条原文');assert.equal(f.d.querySelectorAll('.sf-example:not([hidden])').length,1);assert.deepEqual(f.errors,[]);});
test('compiled incorrect ownership or incomplete binder cannot fake readiness',async t=>{for(const opts of [{profile:{filter_mode:'binder-click'}},{badHandle:{ready:undefined,refresh(){},applyGrouping(){},dispose(){}}}]){const f=fixture(t,opts);await f.w.AnkiSlimApkgHydrate();assert.equal(f.payload.dataset.nativeState,'failed');assert.deepEqual(semantic(f),[]);assert.ok(!f.trace.includes('residual.install'));}});
test('compiled original history lazy media hash/readiness service stays usable',async t=>{const raw='完整原审核 · unchanged',pin=hash(raw),extra='<details id="audit"><summary>audit</summary><pre data-native-history-media="_af_'+pin.slice(0,24)+'.js" data-native-history-sha="'+pin+'">unloaded</pre></details>',f=fixture(t,{extra});f.w.AnkiFinalHistoryEvidence={[pin]:raw};await f.w.AnkiSlimApkgHydrate();const detail=f.d.getElementById('audit');detail.open=true;detail.dispatchEvent(new f.w.Event('toggle'));const pre=detail.querySelector('pre'),deadline=Date.now()+1000;while(pre.dataset.nativeHistoryReady!=='true'&&Date.now()<deadline)await new Promise(r=>setTimeout(r,5));assert.equal(pre.textContent,raw);assert.equal(pre.dataset.nativeHistoryReady,'true');assert.deepEqual(semantic(f),[]);});


test('onInvalid current asynchronous callback visibly marks failure and preserves panel DOM without legacy fallback',async t=>{const f=fixture(t);await f.w.AnkiSlimApkgHydrate();assert.equal(typeof f.invalidCallbacks[0],'function');const before=f.d.querySelector('.sf-report').outerHTML;await Promise.resolve().then(()=>f.invalidCallbacks[0](Error('async binding damaged')));assert.equal(f.payload.dataset.nativeState,'failed');const status=f.d.querySelector('.anki-final-status');assert.ok(status.isConnected);assert.equal(status.hidden,false);assert.equal(status.getAttribute('role'),'status');assert.ok(status.textContent.includes('async binding damaged'));assert.equal(f.d.querySelector('.sf-report').outerHTML,before);assert.deepEqual(semantic(f),[]);const first=status.textContent;f.invalidCallbacks[0](Error('second failure'));assert.equal(status.textContent,first);});
test('onInvalid before ready cannot later overwrite failure with ready or continue residual install',async t=>{let resolve;const f=fixture(t,{ready:new Promise(r=>resolve=r)}),job=f.w.AnkiSlimApkgHydrate();await Promise.resolve();assert.equal(typeof f.invalidCallbacks[0],'function');f.invalidCallbacks[0](Error('damaged during ready'));resolve();await job;assert.equal(f.payload.dataset.nativeState,'failed');assert.ok(!f.trace.includes('residual.install'));assert.deepEqual(semantic(f),[]);});
test('onInvalid stale after cancel and previous generation callback perform zero DOM writes',async t=>{const f=fixture(t);await f.w.AnkiSlimApkgHydrate();const stale=f.invalidCallbacks[0];assert.equal(typeof stale,'function');f.w.AnkiSlimApkgDispose();let before=f.d.documentElement.outerHTML;stale(Error('cancelled'));assert.equal(f.d.documentElement.outerHTML,before);await f.w.AnkiSlimApkgHydrate();before=f.d.documentElement.outerHTML;const observer=new f.w.MutationObserver(()=>{});observer.observe(f.d.documentElement,{attributes:true,subtree:true,characterData:true,childList:true});stale(Error('previous generation'));assert.equal(f.d.documentElement.outerHTML,before);assert.equal(observer.takeRecords().length,0);assert.equal(f.payload.dataset.nativeState,'ready');observer.disconnect();});
test('onInvalid v2 increment exact inverse recovers frozen v1 and full three edits still recover original',()=>{let value=candidate;for(const [a,b]of JSON.parse(read('v2-only-edits.json')).slice().reverse()){assert.equal(value.split(b).length,2);value=value.replace(b,a);}assert.equal(value,read('candidate-slim-v1.js'));assert.equal(hash(value),'3f8abb46ce83bc0e48e54da4e2daf3b0bbc5443a98663ff2c06a01e639c81797');});

test('outer owner cancellation with connected payload and unchanged native generation makes onInvalid perform zero writes',async t=>{const f=fixture(t);await f.w.AnkiSlimApkgHydrate();const version=f.w.__ankiFinalApkgGeneration;assert.equal(f.current(),true);f.setOuterCurrent(false);assert.equal(f.current(),false);assert.equal(f.w.__ankiFinalApkgGeneration,version);assert.equal(f.payload.isConnected,true);const before=f.d.documentElement.outerHTML,mo=new f.w.MutationObserver(()=>{});mo.observe(f.d.documentElement,{subtree:true,attributes:true,characterData:true,childList:true});f.invalidCallbacks[0](Error('outer owner cancelled'));assert.equal(f.d.documentElement.outerHTML,before);assert.equal(mo.takeRecords().length,0);assert.equal(f.payload.dataset.nativeState,'ready');mo.disconnect();});
test('outer owner cancellation while ready pending prevents native ready and residual installation',async t=>{let resolve;const f=fixture(t,{ready:new Promise(r=>resolve=r)}),job=f.w.AnkiSlimApkgHydrate();await Promise.resolve();const generation=f.w.__ankiFinalApkgGeneration;f.setOuterCurrent(false);const before=f.d.documentElement.outerHTML;f.invalidCallbacks[0](Error('stale owner'));resolve();await job;assert.equal(f.w.__ankiFinalApkgGeneration,generation);assert.equal(f.d.documentElement.outerHTML,before);assert.equal(f.payload.dataset.nativeState,undefined);assert.ok(!f.trace.includes('residual.install'));});
